function wrap(t,font,size,w){

  var out=[];

  String(t).split('\n').forEach(function(ln){

    if(!ln.trim()){out.push('');return;}

    var words=ln.split(/\s+/), cur='';

    words.forEach(function(wd){

      var test=cur?cur+' '+wd:wd;

      if(font.widthOfTextAtSize(test,size)>w && cur){out.push(cur);cur=wd;} else cur=test;

    });

    out.push(cur);

  });

  return out;

}

