        function dim(t,x,sz){ pg(); page.drawText(t,{x:x,y:y,size:sz,font:reg,color:MUT}); nl(sz+2.6); }

        function para(t,sz){ wrap(t,reg,sz||10,W-2*M).forEach(function(l){ line(l,sz||10); }); }

