function scopeLines(calc){

  var out=[], on=false;

  String(calc||'').split('\n').forEach(function(l){

    if(/^Approved scope changes since the permit/.test(l)){on=true;return;}

    if(on){ if(!l.trim()||/^Recalculated/.test(l)){on=false;return;} out.push(l.trim()); }

  });

  return out;

}

