        if(B.red[0]||B.red[1]) line3('Reduccion de alcance',-B.red[0],-B.red[1]);

        rule();

        line3('COSTO DE CONSTRUCCION',B.hard[0]+B.cap[0]-B.red[0],B.hard[1]+B.cap[1]-B.red[1],10,bold);

        nl(4);

        t(M,'No sujeto a arbitrios',8.5,bold,MUT); nl(13);

        line3('Costos blandos',B.soft[0],B.soft[1]);

