/* keep case records in step with the money rows: new cases appear by themselves, finished rule follows Settings fid 76 */

var OPENR={'Required \u2014 Pending':1,'Submitted to Municipality':1,'Amendment Approved':1,'Additional Taxes Paid':1};

function rowStage(rows){

  var st={};rows.forEach(function(r){st[r.st]=1;});

  if(Object.keys(st).some(function(s){return OPENR[s];}))return 'A · Prepare request';

  if(st['Waiting \u2014 Structure not passed'])return 'Waiting · Structure not passed';

  if(st['Refund \u2014 money back to us'])return 'Refund owed to us';

  if(st['Not Required'])return 'Not required';

  return 'Closed';

}

function gSync(){

  return xml2('bv92hs97v','API_DoQuery','<query>{3.EX.1}</query><clist>76</clist><fmt>structured</fmt>').then(function(d){

    var fin=(recs(d)[0]||{})['76']||'Ask Priscilla', jobs=[], have={};

    G.cases.forEach(function(c){have[c.cs]=c;});

    var by={};(S.rows||[]).forEach(function(r){(by[r.cs]=by[r.cs]||[]).push(r);});

    Object.keys(by).forEach(function(cs){

      var rows=by[cs], rs=rowStage(rows), c=have[cs], r0=rows[0];

      if(!c){ jobs.push(xml2(CT,'API_AddRecord','<field fid="6">'+esc(cs)+'</field><field fid="7">'+esc(r0.muni||'')+'</field><field fid="8">'+esc(r0.fam||'')+'</field><field fid="9">'+esc(r0.con||'')+'</field><field fid="10">'+esc(rs)+'</field><field fid="11">'+gmdy(gtoday())+'</field>'+(r0.job?'<field fid="67">'+esc(r0.job)+'</field>':''))); return; }

      var ns=null;

      if(c.stage==='Finished · confirm with Priscilla'){ if(fin.indexOf('Yes')===0)ns='A · Prepare request'; else if(fin.indexOf('No')===0)ns='Not required'; }

      else if(!inFlow(c) && rs==='A · Prepare request' && c.stage!=='Closed')ns=rs;

      else if(!inFlow(c) && c.stage!==rs && (rs==='Waiting · Structure not passed'||rs==='Refund owed to us'))ns=rs;

      if(ns&&ns!==c.stage) jobs.push(xml2(CT,'API_EditRecord','<rid>'+c.rid+'</rid><field fid="10">'+esc(ns)+'</field><field fid="11">'+gmdy(gtoday())+'</field>'));

    });

    return Promise.all(jobs).then(function(){return jobs.length;});

  });

}



