/* Quickbase's XML API reads epoch ms as wall-clock time in the app's time zone (Central) and returns the true instant.

   So we send the Central wall clock of the real moment, and show everything in Puerto Rico time. */

function appMs(inst){var o={};new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(new Date(inst)).forEach(function(x){o[x.type]=x.value;});return Date.UTC(+o.year,+o.month-1,+o.day,(+o.hour)%24,+o.minute);}

function vdt(v){if(!v)return '';var d=/^\d{11,}$/.test(v)?new Date(Number(v)):new Date(v);return d.toLocaleString('en-US',{timeZone:'America/Puerto_Rico',month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'});}

function prIso(inst){var o={};new Intl.DateTimeFormat('en-US',{timeZone:'America/Puerto_Rico',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(inst)).forEach(function(x){o[x.type]=x.value;});return o.year+'-'+o.month+'-'+o.day;}

function canopyNote(o){

  var when=vdt(o.t), cs=o.cases||'the case';

  var base='On '+when+', Byrdson Services ('+(o.who||'staff')+') went to the Municipio de '+o.muni+' to pay the '+(o.purpose==='Original permit taxes'?'construction permit taxes (arbitrios and patente)':'arbitrios and patente for the construction permit amendment')+' for '+cs+'.';

  if(o.outcome==='Paid')return base+' Payment was made'+(o.amt?' ('+money(o.amt)+')':'')+'. Receipt on file in Quickbase.';

  var why={'No one available to take payment':'no one was available at the municipality to accept the payment','Office closed':'the office was closed','System down':'the municipality\'s payment system was down','Documents refused':'the municipality did not accept the documents presented','Other':'payment could not be completed'}[o.outcome]||'payment could not be completed';

  return base+' Payment could not be made: '+why+'.'+(o.note?' '+o.note:'')+' Evidence (time-stamped photo'+(o.roster?' and sign-in sheet':'')+') is on file in Quickbase. Byrdson will return to complete the payment.';

}

