    if(/^-{3,}.*-{3,}$/.test(s)){ close(); if(/PRELIMINARY|INITIAL|RISK ASSESSMENT|DAMAGE ASSESSMENT/i.test(s)) sc=''; continue; }

    if(XR_GROUP.test(s)&&!/\d{2,}/.test(s)){ close(); if(s.trim().split(' ')[0]!==grp.split(' ')[0]) sc=''; grp=s.trim(); continue; }

    if((m=s.match(XR_ITEM))){ close();

      var rest=m[5], rev=/^REVISED\b/.test(rest), nums=rest.match(/-?[\d,]*\.\d{2}/g)||[];

      var noteTail=rev?rest.replace(/^REVISED\s*/,''):rest.replace(/^(\s*-?[\d,]*\.\d{2})+\s*/,'');

      cur={n:+m[1],grp:grp,desc:m[2].trim(),qty:xNum(m[3]),unit:m[4],uc:null,rcv:rev?null:(nums.length?xNum(nums[nums.length-1]):null),rev:rev,sc:sc,notes:[]};

      if(!rev&&nums.length>=5){ cur.uc=xNum(nums[0])||xNum(nums[1]); }

      if(noteTail&&!/^[\d,.\s-]+$/.test(noteTail)) cur.notes.push(noteTail);

      /* a short first line after the item is the wrapped end of the description */

      var nx=L[i+1]||''; if(nx&&!XR_ITEM.test(nx)&&nx.length<=45&&!/[.:]$/.test(nx)&&!/^(Municipality|Totals?:|-{3})/.test(nx)&&!/Page:\s*\d/.test(nx)&&!/\$/.test(nx)&&!XR_GROUP.test(nx)){ cur.desc+=' '+nx.trim(); i++; }

      continue; }

    if(cur){ cur.notes.push(s); if((m=s.match(/\$([\d,]+\.\d{2})\s*[x\*]\s*([\d.]+)%/))&&/Construction/i.test(cur.desc)&&!cur.rev) meta.construction=xNum(m[1]); }

